//! Parity with the Go `charm-a11y` package.
//!
//! `report()` mirrors `reference/go/charm-a11y/cmd/parity/main.go` section by
//! section. The golden file is generated by that Go program and compared after
//! ANSI removal, line endings and trailing spaces are normalized.

use std::collections::HashMap;

use charm_a11y::{strip_ansi, Profile};
use charm_parity::assert_golden;
use lipgloss::{
    block_border, double_border, normal_border, outer_half_block_border, rounded_border,
    thick_border, Style,
};

const DETECT_CASES: &[(&str, &[(&str, &str)])] = &[
    ("vazio", &[]),
    ("no-color-vazio", &[("NO_COLOR", "")]),
    ("no-color-1", &[("NO_COLOR", "1")]),
    ("no-color-0", &[("NO_COLOR", "0")]),
    ("clicolor-0", &[("CLICOLOR", "0")]),
    ("dumb", &[("TERM", "dumb")]),
    ("term-comum", &[("TERM", "xterm-256color")]),
    ("high-contrast", &[("A11Y_HIGH_CONTRAST", " TRUE ")]),
    ("reduced-motion", &[("A11Y_REDUCED_MOTION", "1")]),
    ("screen-reader", &[("A11Y_SCREEN_READER", "true")]),
    ("ascii", &[("ASCII", "1")]),
    ("a11y-ascii-falso", &[("A11Y_ASCII", "false")]),
    ("columns", &[("COLUMNS", "120")]),
    ("columns-invalido", &[("COLUMNS", "largo")]),
    ("columns-negativo", &[("COLUMNS", "-1")]),
    (
        "combinacao",
        &[
            ("TERM", "dumb"),
            ("A11Y_HIGH_CONTRAST", "1"),
            ("A11Y_REDUCED_MOTION", "true"),
            ("A11Y_SCREEN_READER", "1"),
            ("COLUMNS", "40"),
        ],
    ),
    (
        "espacos",
        &[("A11Y_HIGH_CONTRAST", " true "), ("CLICOLOR", " 0 ")],
    ),
];

const SANITIZE_INPUTS: &[&str] = &[
    "\x1b[1m┌─┐\x1b[0m\n│✓│\n└─┘ → 100% …",
    "\x1b]0;título\x07corpo ★ «ok» ±1 ≤ ≥",
    "世界 ✓ ▶ ◀ • ≠ ≈ × ÷",
    "\x1b[31m┌─┐ ✓ 世界\x1b[0m",
];

const STRIP_INPUTS: &[&str] = &[
    "\x1b[31mvermelho\x1b[0m",
    "\x1b[1;38;5;196mX\x1b[0m",
    "\x1b[2J\x1b[1;1Htela",
    "\x1b[?25lsegredo\x1b[?25h",
    "\x1b]0;título\x07corpo",
    "\x1b]8;;https://example.com\x1b\\link\x1b]8;;\x1b\\",
    "\x1b(Btexto",
    "\x1b#8",
    "a[0] = [31m]",
    "100% [ok]",
    "\x1b[1mOlá, 世界! 🎉\x1b[0m",
    "a\x1b[31mb\x1b[0mc",
    "\x1b[31",
    "\x1b]0;título",
    "ok\x1b]0;título",
    "\x1b",
    "",
];

fn unicode() -> Profile {
    Profile {
        unicode: true,
        ..Profile::default()
    }
}

fn screen_reader() -> Profile {
    Profile {
        screen_reader: true,
        ..Profile::default()
    }
}

fn report() -> String {
    let mut lines: Vec<String> = Vec::new();
    detect_section(&mut lines);
    symbol_and_sanitize_section(&mut lines);
    borders_section(&mut lines);
    style_section(&mut lines);
    frames_and_announce_section(&mut lines);
    strip_section(&mut lines);

    let mut out = lines.join("\n");
    out.push('\n');
    out
}

fn detect_section(lines: &mut Vec<String>) {
    lines.push("## detect".to_owned());
    for (name, pairs) in DETECT_CASES {
        let map: HashMap<&str, &str> = pairs.iter().copied().collect();
        let profile = Profile::detect_from(|key| map.get(key).map(|v| (*v).to_owned()));
        lines.push(format!("{name}: {}", profile.describe()));
    }
}

fn symbol_and_sanitize_section(lines: &mut Vec<String>) {
    let uni = unicode();
    let ascii = Profile::default();

    lines.push("## symbol".to_owned());
    lines.push(format!(
        "{} {}",
        uni.symbol("✓", "ok"),
        ascii.symbol("✓", "ok")
    ));

    lines.push("## sanitize".to_owned());
    for input in SANITIZE_INPUTS {
        lines.push(format!("unicode: {}", uni.sanitize(input)));
        lines.push(format!("ascii: {}", ascii.sanitize(input)));
    }
}

fn borders_section(lines: &mut Vec<String>) {
    let ascii = Profile::default();

    lines.push("## borders".to_owned());
    let borders = [
        ("normal", normal_border()),
        ("rounded", rounded_border()),
        ("thick", thick_border()),
        ("double", double_border()),
        ("block", block_border()),
        ("outer-half-block", outer_half_block_border()),
    ];
    for (name, border) in borders {
        lines.push(format!("{name}:"));
        lines.push(ascii.style(Style::new().border(border)).render("ok"));
    }
    lines.push("rounded-unicode:".to_owned());
    lines.push(
        unicode()
            .style(Style::new().border(rounded_border()))
            .render("ok"),
    );
}

fn style_section(lines: &mut Vec<String>) {
    let base = Style::new()
        .foreground("#ff0000")
        .background("#00ff00")
        .border(rounded_border())
        .border_foreground("#0000ff")
        .padding(0, 1, 0, 1);

    lines.push("## style".to_owned());
    lines.push("no-color-unicode:".to_owned());
    lines.push(
        Profile {
            no_color: true,
            unicode: true,
            ..Profile::default()
        }
        .style(base.clone())
        .render("x"),
    );
    lines.push("no-color-ascii:".to_owned());
    lines.push(
        Profile {
            no_color: true,
            ..Profile::default()
        }
        .style(base.clone())
        .render("x"),
    );
    lines.push("zero-profile:".to_owned());
    lines.push(Profile::default().style(base).render("x"));
    lines.push("high-contrast:".to_owned());
    lines.push(
        Profile {
            high_contrast: true,
            unicode: true,
            ..Profile::default()
        }
        .style(Style::new().faint(true))
        .render("dim"),
    );
}

fn frames_and_announce_section(lines: &mut Vec<String>) {
    let frames = ["a", "b", "c"];
    let empty: &[&str] = &[];
    let reduced = Profile {
        reduced_motion: true,
        ..Profile::default()
    };

    lines.push("## frames".to_owned());
    lines.push(Profile::default().frames(&frames).join(" "));
    lines.push(reduced.frames(&frames).join(" "));
    lines.push(reduced.frames(empty).join(" "));
    lines.push(Profile::default().frames(empty).join(" "));

    let sr = screen_reader();
    lines.push("## announce".to_owned());
    lines.push(sr.announce(&format!("\x1b[32m{}\x1b[0m\n{}\t!", "ok", "tudo certo")));
    lines.push(sr.announce("a  b\n\nc"));
    lines.push(sr.announce("\x1b]0;título\x07corpo"));
    lines.push(sr.announce("a\x00b\x07c"));
    lines.push(sr.announce("100% [pronto]\x1b[0m"));
    lines.push(sr.announce("ação concluída: ✓"));
    lines.push(sr.announce(&format!("etapa {} de {}", 2, 3)));
    lines.push(sr.announce(" \n\t "));
}

fn strip_section(lines: &mut Vec<String>) {
    lines.push("## strip".to_owned());
    for input in STRIP_INPUTS {
        lines.push(format!("strip: {}", strip_ansi(input)));
    }
}

#[test]
fn a11y_golden() {
    assert_golden("a11y", &report());
}
